import * as T from './vendor/three.module.js';import {createCampus} from './campus.js?v=9';import {createStudent} from './student.js?v=9';import {createFilmProps} from './film-props.js?v=9';import {SHOTS,FILM_DURATION,PHOTO_TIME} from './film-sequences.js?v=9';import {evaluateFilm,applyFilmFrame} from './film-director.js?v=9';
const $=id=>document.getElementById(id),screen=$('screen'),picture=$('picture'),ctx=picture.getContext('2d'),freeze=document.createElement('canvas');let frozen=false,playing=false,time=0,ready=false,playRequest=0;
const music=new Audio('./assets/campus-score.mp3?v=9');music.preload='auto';
const scene=new T.Scene();scene.background=new T.Color('#d7e3d9');scene.fog=new T.Fog('#d7e3d9',1250,2200);
const camera=new T.PerspectiveCamera(39,16/9,.1,2800);let renderer;
try{renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance',preserveDrawingBuffer:true});}catch(e){$('loading').textContent='当前浏览器未能启用三维渲染，请开启硬件加速后重试。';throw e;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;screen.prepend(renderer.domElement);
const hemi=new T.HemisphereLight('#e8f5ed','#919474',2.1),sun=new T.DirectionalLight('#fff1d2',3.1),fill=new T.DirectionalLight('#cbe5db',.6);sun.position.set(-280,450,240);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-430,right:430,top:430,bottom:-430,near:1,far:1150});sun.shadow.bias=-.00035;sun.shadow.normalBias=.1;fill.position.set(200,150,-250);scene.add(hemi,sun,fill);
const backdrop=new T.Mesh(new T.PlaneGeometry(12000,12000),new T.MeshStandardMaterial({color:'#d7e3d9',roughness:1}));backdrop.rotation.x=-Math.PI/2;backdrop.position.y=-45;backdrop.receiveShadow=true;scene.add(backdrop);
const campus=createCampus(),student=createStudent();scene.add(campus.group,student.group,createFilmProps());
$('shot').innerHTML=SHOTS.map((s,i)=>`<option value="${s.startTime}">${String(i+1).padStart(2,'0')} · ${s.title}</option>`).join('');
const clock=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
function caption(f,W,H){if(!f.caption||!f.captionOpacity)return;ctx.save();ctx.globalAlpha=f.captionOpacity;ctx.textAlign='left';ctx.textBaseline='top';const x=W*.052,y=H*.785;ctx.font=`${W*.028}px FilmLabels, sans-serif`;const cnWidth=ctx.measureText(f.caption[0]).width;ctx.font=`${W*.012}px Arial`;const width=Math.max(cnWidth,ctx.measureText(f.caption[1]).width)+W*.04;ctx.fillStyle='rgba(20,46,35,.86)';ctx.fillRect(x-W*.016,y-H*.013,width+W*.016,H*.129);ctx.fillStyle='#e5c988';ctx.fillRect(x-W*.016,y-H*.013,W*.004,H*.129);ctx.fillStyle='#fffff3';ctx.font=`${W*.028}px FilmLabels, sans-serif`;ctx.fillText(f.caption[0],x,y);ctx.fillStyle='#d2e2d3';ctx.font=`${W*.012}px Arial`;ctx.fillText(f.caption[1],x,y+H*.069);ctx.restore();}
function overlay(f){const W=picture.width,H=picture.height;ctx.clearRect(0,0,W,H);caption(f,W,H);if(f.photo){if(!frozen){freeze.width=renderer.domElement.width;freeze.height=renderer.domElement.height;freeze.getContext('2d').drawImage(renderer.domElement,0,0);frozen=true;}const u=f.photoProgress,w=W*(1-.10*u),h=H*(1-.20*u),x=(W-w)/2,y=H*.03*u;ctx.fillStyle='#e9eee5';ctx.fillRect(0,0,W,H);ctx.drawImage(freeze,x,y,w,h);ctx.strokeStyle='white';ctx.lineWidth=W*.005*u;ctx.strokeRect(x,y,w,h);ctx.fillStyle='#234437';ctx.textAlign='center';ctx.font=`${W*.023}px Arial`;ctx.fillText('The Education University of Hong Kong',W/2,y+h+H*.057);ctx.fillStyle='#52645c';ctx.font=`${W*.012}px Arial`;ctx.fillText('AI-assisted Web3D & New Media Experiment',W/2,y+h+H*.105);ctx.font=`${W*.009}px Arial`;ctx.fillText('Music: Carefree · Kevin MacLeod (incompetech.com) · CC BY 4.0 · edited excerpt',W/2,H*.969);ctx.font=`${W*.0075}px Arial`;ctx.fillText('creativecommons.org/licenses/by/4.0/',W/2,H*.989);}else frozen=false;if(f.flash>0){ctx.fillStyle=`rgba(255,255,255,${f.flash*.78})`;ctx.fillRect(0,0,W,H);}if(f.fade>0){ctx.fillStyle=`rgba(0,0,0,${f.fade})`;ctx.fillRect(0,0,W,H);}}
function render(t){const f=evaluateFilm(t,campus);applyFilmFrame(f,camera,student);renderer.render(scene,camera);overlay(f);$('seek').value=t;$('time').textContent=`${clock(t)} / 01:30`;$('shot').value=f.shot.startTime;$('phase').textContent=['','第一幕 · Arrival / Entering the Campus','第二幕 · Discovering the Campus','第三幕 · Experiencing the Campus'][f.shot.act];screen.dataset.time=t.toFixed(3);screen.dataset.shot=f.shot.id;}
function resize(){const W=Math.max(320,screen.clientWidth),H=W*9/16;renderer.setSize(W,H,false);picture.width=renderer.domElement.width;picture.height=renderer.domElement.height;if(ready)render(time);}new ResizeObserver(resize).observe(screen);resize();
function setPlaying(value){playing=value;$('play').textContent=value?'暂停':time>=FILM_DURATION?'重播':'播放';}
function startMusic(){const request=++playRequest;music.play().catch(()=>{if(request===playRequest&&playing){setPlaying(false);$('music-status').hidden=false;$('music-status').textContent='音乐暂未能播放，请点击播放重试。';}});}
function play(){if(!ready)return;if(playing){++playRequest;music.pause();setPlaying(false);return;}if(time>=FILM_DURATION)seek(0);$('start').hidden=true;$('music-status').hidden=true;music.currentTime=time;setPlaying(true);startMusic();}
function seek(value){time=Math.max(0,Math.min(FILM_DURATION,value));music.currentTime=time;frozen=false;if(time>=FILM_DURATION){++playRequest;music.pause();setPlaying(false);}if(ready)render(time);}
$('play').onclick=play;$('start').onclick=play;
$('restart').onclick=()=>{++playRequest;music.pause();setPlaying(false);seek(0);play();};
$('seek').oninput=e=>seek(Number(e.target.value));$('shot').onchange=e=>seek(Number(e.target.value));
$('music').onclick=()=>{music.muted=!music.muted;$('music').textContent=music.muted?'音乐：关':'音乐：开';$('music').setAttribute('aria-pressed',String(!music.muted));};
$('full').onclick=()=>screen.requestFullscreen?.();
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','BUTTON','A'].includes(e.target.tagName)){e.preventDefault();play();}});
document.addEventListener('visibilitychange',()=>{if(!playing)return;if(document.hidden){++playRequest;music.pause();}else startMusic();});
music.addEventListener('ended',()=>{time=FILM_DURATION;setPlaying(false);if(ready)render(time);});
Promise.all([student.ready,document.fonts.load('28px FilmLabels')]).then(([ok])=>{if(!ok){$('loading').textContent='人物加载失败，请刷新重试。';return;}ready=true;$('loading').hidden=true;$('start').hidden=false;$('play').disabled=false;$('restart').disabled=false;render(0);});
function tick(){requestAnimationFrame(tick);if(playing&&ready&&!document.hidden&&!music.seeking){time=Math.min(FILM_DURATION,music.currentTime);render(time);if(time>=FILM_DURATION){music.pause();setPlaying(false);}}}requestAnimationFrame(tick);
